def _compute_warehouse_id(self):
    for line in self:
        line.warehouse_id = line.order_id.warehouse_id
        if line.route_ids:
            domain = [
                ('location_dest_id', 'in', line.order_id.partner_shipping_id.property_stock_customer.ids),
                ('action', '!=', 'push'),
            ]
            # prefer rules on the route itself even if they pull from a different warehouse than the SO's
            rules = sorted(
                self.env['stock.rule'].search(
                    domain=Domain.AND([[('route_id', 'in', line.route_ids.ids)], domain]),
                    order='route_sequence, sequence'
                ),
                # if there are multiple rules on the route, prefer those that pull from the SO's warehouse
                # or those that are not warehouse specific
                key=lambda rule: 0 if rule.location_src_id.warehouse_id in (False, line.order_id.warehouse_id) else 1
            )
            if rules:
                line.warehouse_id = rules[0].location_src_id.warehouse_id

def _compute_qty_to_deliver(self):
    """Compute the visibility of the inventory widget."""
    for line in self:
        line.qty_to_deliver = line.product_uom_qty - line.qty_delivered
        if line.state in ('draft', 'sent', 'sale') and line.is_storable and line.product_uom_id and line.qty_to_deliver > 0:
            if line.state == 'sale' and all(m.state in ['done', 'cancel'] for m in line.move_ids):
                line.display_qty_widget = False
            else:
                line.display_qty_widget = True
        else:
            line.display_qty_widget = False

def _compute_is_mto(self):
    """ Verify the route of the product based on the warehouse
        set 'is_available' at True if the product availability in stock does
        not need to be verified, which is the case in MTO, Drop-Shipping
    """
    self.is_mto = False
    for line in self:
        if not line.display_qty_widget:
            continue
        product = line.product_id
        product_routes = line.route_ids or (product.route_ids + product.categ_id.total_route_ids)

        # Check MTO. sudo needed in case cross-company warehouse
        mto_route = line.warehouse_id.sudo().mto_pull_id.route_id
        if not mto_route:
            try:
                mto_route = self.env['stock.warehouse']._find_or_create_global_route('stock.route_warehouse0_mto', _('Replenish on Order (MTO)'), create=False)
            except UserError:
                # if route MTO not found in ir_model_data, we treat the product as in MTS
                pass

        if mto_route and mto_route in product_routes:
            line.is_mto = True
        else:
            line.is_mto = False

def _prepare_qty_delivered(self):
    delivered_qties = super()._prepare_qty_delivered()
    for line in self:  # TODO: maybe one day, this should be done in SQL for performance sake
        if line.qty_delivered_method == 'stock_move':
            qty = 0.
            if line.order_id.sudo().warehouse_id.company_id != self.order_id.company_id:
                # If the selected warehouse belongs to another company, need to fetch their moves regardless.
                line = line.sudo()
            outgoing_moves, incoming_moves = line._get_outgoing_incoming_moves()
            for move in outgoing_moves:
                if move.state != 'done':
                    continue
                qty += move.uom_id._compute_quantity(move.quantity, line.product_uom_id, rounding_method='HALF-UP')
            for move in incoming_moves:
                # An unlinked move coming from a customer is still a real return, only skip unlinked non-returns (dropship receipts).
                if move.state != 'done' or (
                    not move.origin_returned_move_id
                    and not move.location_id._is_outgoing()
                    and line.product_uom_qty > 0
                    and not move.picking_id.return_id
                ):
                    continue
                qty -= move.uom_id._compute_quantity(move.quantity, line.product_uom_id, rounding_method='HALF-UP')

            delivered_qties[line] += qty
    return delivered_qties

def create(self, vals_list):
    lines = super().create(vals_list)
    lines.filtered(
        lambda line: line.state == 'sale' and line.product_id.type == 'consu'
    )._action_launch_stock_rule()
    return lines

def write(self, vals):
    lines = self.env['sale.order.line']
    if 'product_uom_qty' in vals:
        lines = self.filtered(lambda r: r.state == 'sale' and not r.is_expense)

    previous_product_uom_qty = {line.id: line.product_uom_qty for line in lines}
    res = super().write(vals)
    if lines:
        lines._action_launch_stock_rule(previous_product_uom_qty=previous_product_uom_qty)
    return res

def _compute_product_updatable(self):
    super()._compute_product_updatable()
    for line in self:
        if line.move_ids.filtered(lambda m: m.state != 'cancel'):
            line.product_updatable = False

def _inverse_customer_lead(self):
    for line in self:
        if line.state == 'sale' and not line.order_id.commitment_date:
            # Propagate deadline on related stock move
            line.move_ids.date_deadline = line.order_id.date_order + timedelta(days=line.customer_lead or 0.0)

def _get_outgoing_incoming_moves(self, strict=True):
    """ Return the outgoing and incoming moves of the sale order line.
        @param strict: If True, only consider the moves that are strictly delivered to the customer (old behavior).
                       If False, consider the moves that were created through the initial rule of the delivery route,
                       to support the new push mechanism.
    """
    outgoing_moves_ids = set()
    incoming_moves_ids = set()

    moves = self.move_ids.filtered(lambda m: m.location_dest_usage != 'inventory' and self.product_id == m.product_id)
    if moves and not strict:
        # The first move created was the one created from the intial rule that started it all.
        # Look at every move ever created for this line, including cancelled ones: if the
        # triggering move gets cancelled later on (e.g. SO cancellation), the rule that started
        # the chain must stay the same, otherwise remaining done moves get wrongly re-classified.
        sorted_moves = moves.sorted('id')
        triggering_rule_ids = []
        seen_wh_ids = set()
        for move in sorted_moves:
            # A move without warehouse (created by a rule without warehouse) does not start a new chain
            if move.warehouse_id.id not in seen_wh_ids and move.rule_id and (move.warehouse_id or not triggering_rule_ids):
                triggering_rule_ids.append(move.rule_id.id)
                seen_wh_ids.add(move.warehouse_id.id)
    moves = moves.filtered(lambda m: m.state != 'cancel')
    if self.env.context.get('accrual_entry_date'):
        accrual_date = fields.Date.from_string(self.env.context['accrual_entry_date'])
        moves = moves.filtered(lambda r: fields.Date.context_today(r, r.date) <= accrual_date)

    for move in moves:
        if not move._is_dropshipped_returned() and (
            (strict and move.location_dest_id._is_outgoing()) or (
            not strict and move.rule_id.id in triggering_rule_ids and
            (move.forecasted_location_id or move.location_dest_id)._is_outgoing()
        )):
            if not move.origin_returned_move_id or (move.origin_returned_move_id and move.to_refund):
                outgoing_moves_ids.add(move.id)
        elif move.to_refund and (
            (strict and move._is_incoming() or move.location_id._is_outgoing()) or (
            not strict and move.rule_id.id in triggering_rule_ids and
            (move.forecasted_location_id or move.location_dest_id).usage == 'internal'
        )):
            incoming_moves_ids.add(move.id)

    return self.env['stock.move'].browse(outgoing_moves_ids), self.env['stock.move'].browse(incoming_moves_ids)

def _prepare_reference_vals(self):
    return {
        'name': self.order_id.name,
        'sale_ids': [(4, self.order_id.id)],
    }

def _create_procurements(self, product_qty, procurement_uom, values):
    self.ensure_one()
    origin = self.order_id.name
    if self.order_id.company_id != self.sudo().warehouse_id.company_id:
        origin += f" ({self.order_id.company_id.name})"
    return [self.env['stock.rule'].Procurement(
        self.product_id, product_qty, procurement_uom, self._get_location_final(),
        self.product_id.display_name, origin, self.order_id.company_id, values)]

def _update_line_quantity(self, values):
    precision = self.env['decimal.precision'].precision_get('Product Unit')
    line_products = self.filtered(lambda l: l.product_id.type == 'consu')
    if line_products.mapped('qty_delivered') and float_compare(values['product_uom_qty'], max(line_products.mapped('qty_delivered')), precision_digits=precision) == -1:
        raise UserError(_('The ordered quantity of a sale order line cannot be decreased below the amount already delivered. Instead, create a return in your inventory.'))
    super(SaleOrderLine, self)._update_line_quantity(values)

def _get_product_catalog_lines_data(self, *args, **kwargs) -> dict:
    """Override of `sale` to add the delivered quantity."""
    return {
        **super()._get_product_catalog_lines_data(*args, **kwargs),
        "deliveredQty": sum(
            self.mapped(
                lambda line: line.product_uom_id._compute_quantity(
                    qty=line.qty_delivered, to_unit=self._get_product_uom()
                )
            )
        ),
    }

def _is_returnable(self):
    """Return whether this line contains a product eligible for return."""
    self.ensure_one()
    return (
        self.product_type == "consu"
        and self._is_product_line()
        and self.has_valued_move_ids()
        and not self.combo_item_id
    )

def _compute_display_name(self):
    super()._compute_display_name()
    for workcenter in self:
        # Show the red icon(workcenter is blocked) only when the Gantt view is accessed from MRP > Planning > Planning by Workcenter.
        if self.env.context.get('group_by') and self.env.context.get('show_workcenter_status') and workcenter.working_state == 'blocked':
            workcenter.display_name = f"{workcenter.display_name}\u00A0\u00A0🔴"

def _check_alternative_workcenter(self):
    for workcenter in self:
        if workcenter in workcenter.alternative_workcenter_ids:
            raise ValidationError(_("Workcenter %s cannot be an alternative of itself.", workcenter.name))

def _compute_kanban_dashboard_graph(self):
    week_range, date_start, date_stop = self._get_week_range_and_first_last_days()
    load_data = self._get_workcenter_load_per_week(week_range, date_start, date_stop)
    load_graph_data = self._prepare_graph_data(load_data, week_range)
    for wc in self:
        wc.kanban_dashboard_graph = json.dumps(load_graph_data[wc.id])

def _get_workcenter_load_per_week(self, week_range, date_start, date_stop):
    load_data = {rec: {} for rec in self}
    # demo data
    has_workorder = self.env['mrp.workorder'].search_count([('workcenter_id', 'in', self.ids)], limit=1)
    if not has_workorder:
        for wc in self:
            load_limit = 40     # default max load per week is 40 hours on a new workcenter
            load_data[wc] = {week_start: randint(0, int(load_limit * 2)) for week_start in week_range}
        return load_data

    result = self.env['mrp.workorder']._read_group(
        [('workcenter_id', 'in', self.ids), ('state', 'in', ('pending', 'waiting', 'ready', 'progress')),
         ('production_date', '>=', date_start), ('production_date', '<=', date_stop)],
        ['workcenter_id', 'production_date:week'], ['duration_expected:sum'])
    for r in result:
        load_in_hours = round(r[2] / 60, 1)
        load_data[r[0]].update({r[1]: load_in_hours})
    return load_data

def _prepare_graph_data(self, load_data, week_range):
    graph_data = {wid: [] for wid in self._ids}
    has_workorder = self.env['mrp.workorder'].search_count([('workcenter_id', 'in', self.ids)], limit=1)
    for workcenter in self:
        load_limit = workcenter.resource_calendar_id.hours_per_week
        wc_data = {'is_sample_data': not has_workorder, 'labels': list(week_range.values())}
        load_bar = []
        excess_bar = []
        for week_start in week_range:
            load_bar.append(min(load_data[workcenter].get(week_start, 0), load_limit))
            excess_bar.append(max(float_round(load_data[workcenter].get(week_start, 0) - load_limit, precision_digits=1, rounding_method='HALF-UP'), 0))
        wc_data['values'] = [load_bar, load_limit, excess_bar]
        graph_data[workcenter.id].append(wc_data)
    return graph_data

def _compute_working_state(self):
    # We search for a productivity line associated to this workcenter having no `date_end`.
    # If we do not find one, the workcenter is not currently being used. If we find one, according
    # to its `type_loss`, the workcenter is either being used or blocked.
    time_log_by_workcenter = {}
    for time_log in self.env['mrp.workcenter.productivity'].search([
        ('workcenter_id', 'in', self.ids),
        ('date_end', '=', False),
    ]):
        wc = time_log.workcenter_id
        if wc not in time_log_by_workcenter:
            time_log_by_workcenter[wc] = time_log

    for workcenter in self:
        time_log = time_log_by_workcenter.get(workcenter._origin)
        if not time_log:
            # the workcenter is not being used
            workcenter.working_state = 'normal'
        elif time_log.loss_type in ('productive', 'performance'):
            # the productivity line has a `loss_type` that means the workcenter is being used
            workcenter.working_state = 'done'
        else:
            # the workcenter is blocked
            workcenter.working_state = 'blocked'

def _compute_oee(self):
    time_data = self.env['mrp.workcenter.productivity']._read_group(
        domain=[
            ('date_start', '>=', fields.Datetime.to_string(datetime.now() - relativedelta.relativedelta(months=1))),
            ('workcenter_id', 'in', self.ids),
            ('date_end', '!=', False),
        ],
        groupby=['workcenter_id', 'loss_type'],
        aggregates=['duration:sum'],
    )
    time_by_workcenter = defaultdict(lambda: {'productive_time': 0.0, 'blocked_time': 0.0})
    for data in time_data:
        workcenter, loss_type, duration = data
        time_to_update = 'productive_time' if loss_type == 'productive' else 'blocked_time'
        time_by_workcenter[workcenter.id][time_to_update] += duration
    for workcenter in self:
        workcenter_time = time_by_workcenter[workcenter.id]
        productive_time = workcenter_time['productive_time']
        if productive_time:
            blocked_time = workcenter_time['blocked_time']
            workcenter.oee = float_round(productive_time * 100.0 / (productive_time + blocked_time), precision_digits=2)
        else:
            workcenter.oee = 0.0

def _compute_performance(self):
    wo_data = self.env['mrp.workorder']._read_group([
        ('date_start', '>=', fields.Datetime.to_string(datetime.now() - relativedelta.relativedelta(months=1))),
        ('workcenter_id', 'in', self.ids),
        ('state', '=', 'done')], ['workcenter_id'], ['duration_expected:sum', 'duration:sum'])
    duration_expected = {workcenter.id: expected for workcenter, expected, __ in wo_data}
    duration = {workcenter.id: duration for workcenter, __, duration in wo_data}
    for workcenter in self:
        if duration.get(workcenter.id):
            workcenter.performance = 100 * duration_expected.get(workcenter.id, 0.0) / duration[workcenter.id]
        else:
            workcenter.performance = 0.0

def _compute_has_routing_lines(self):
    for workcenter in self:
        workcenter.has_routing_lines = self.env['mrp.routing.workcenter'].search_count([('workcenter_id', 'in', workcenter.ids)], limit=1)

def unblock(self):
    self.ensure_one()
    if self.working_state != 'blocked':
        raise exceptions.UserError(_("It has already been unblocked."))
    times = self.env['mrp.workcenter.productivity'].search([('workcenter_id', '=', self.id), ('date_end', '=', False)])
    self.sudo().message_post(
        body=self.env._("Work Center Unblocked")
    )
    times.write({'date_end': datetime.now()})
    return True

def write(self, vals):
    if 'company_id' in vals:
        self.resource_id.company_id = vals['company_id']
    return super(MrpWorkcenter, self).write(vals)

def action_show_operations(self):
    self.ensure_one()
    action = self.env['ir.actions.actions']._for_xml_id('mrp.mrp_routing_action')
    action['domain'] = [('workcenter_id', '=', self.id)]
    action['context'] = {
        'default_workcenter_id': self.id,
    }
    return action

def action_work_order(self):
    action = self.env["ir.actions.actions"]._for_xml_id("mrp.action_work_orders")
    return action

def action_archive(self):
    res = super().action_archive()
    filtered_workcenters = ", ".join(workcenter.name for workcenter in self.filtered('routing_line_ids'))
    if filtered_workcenters:
        return {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
            'title': _("Note that archived work center(s): '%s' is/are still linked to active Bill of Materials, which means that operations can still be planned on it/them. "
                       "To prevent this, deletion of the work center is recommended instead.", filtered_workcenters),
            'type': 'warning',
            'sticky': True,  #True/False will display for few seconds if false
            'next': {'type': 'ir.actions.act_window_close'},
            },
        }
    return res

def _get_capacity(self, product, unit, default_capacity=1):
    capacity = self.capacity_ids.sorted(lambda c: (
        not (c.product_id == product and c.uom_id == product.uom_id),
        not (not c.product_id and c.uom_id == unit),
        not (not c.product_id and c.uom_id == product.uom_id),
    ))[:1]
    if capacity and capacity.product_id in [product, self.env['product.product']] and capacity.uom_id in [product.uom_id, unit]:
        if float_is_zero(capacity.capacity, 0):
            return (default_capacity, capacity.time_start, capacity.time_stop)
        return (capacity.uom_id._compute_quantity(capacity.capacity, unit), capacity.time_start, capacity.time_stop)
    return (default_capacity, self.time_start, self.time_stop)

def _convert_to_duration(self, date_start, date_stop, workcenter=False):
    """ Convert a date range into a duration in minutes.
    If the productivity type is not from an employee (extra hours are allow)
    and the workcenter has a calendar, convert the dates into a duration based on
    working hours.
    """
    duration = 0
    for productivity_loss in self:
        if (productivity_loss.loss_type not in ('productive', 'performance')) and workcenter and workcenter.resource_calendar_id:
            r = workcenter._get_work_days_data_batch(date_start, date_stop)[workcenter.id]['hours']
            duration = max(duration, r * 60)
        else:
            duration = max(duration, (date_stop - date_start).total_seconds() / 60.0)
    return round(duration, 2)

def _get_default_company_id(self):
    company_id = False
    if self.env.context.get('default_company_id'):
        company_id = self.env.context['default_company_id']
    if not company_id and self.env.context.get('default_workorder_id'):
        workorder = self.env['mrp.workorder'].browse(self.env.context['default_workorder_id'])
        company_id = workorder.company_id
    if not company_id and self.env.context.get('default_workcenter_id'):
        workcenter = self.env['mrp.workcenter'].browse(self.env.context['default_workcenter_id'])
        company_id = workcenter.company_id
    if not company_id:
        company_id = self.env.company
    return company_id

def _compute_duration(self):
    for blocktime in self:
        if blocktime.date_start and blocktime.date_end:
            blocktime.duration = blocktime.loss_id._convert_to_duration(blocktime.date_start.replace(microsecond=0), blocktime.date_end.replace(microsecond=0), blocktime.workcenter_id)
        else:
            blocktime.duration = 0.0

def _duration_changed(self):
    if not self.date_end:
        return
    self.date_start = self.date_end - timedelta(minutes=self.duration)
    self._loss_type_change()

def _date_start_changed(self):
    if not self.date_start:
        return
    self.date_end = self.date_start + timedelta(minutes=self.duration)
    self._loss_type_change()

def _date_end_changed(self):
    if not self.date_end:
        return
    self.date_start = self.date_end - timedelta(minutes=self.duration)
    self._loss_type_change()

def _check_open_time_ids(self):
    for workorder in self.workorder_id:
        open_time_ids_by_user = self.env["mrp.workcenter.productivity"]._read_group(
            [("id", "in", workorder.time_ids.ids), ("date_end", "=", False)],
            ["user_id"], having=[("__count", ">", 1)],
        )
        if open_time_ids_by_user:
            raise ValidationError(_('The Workorder (%s) cannot be started twice!', workorder.display_name))

def button_block(self):
    self.ensure_one()
    self.workcenter_id.order_ids.end_all()
    self.workcenter_id.sudo().message_post(
        body=self.env._("Work Center Blocked: %s", self.loss_id.display_name)
    )

def _loss_type_change(self):
    self.ensure_one()
    if self.workorder_id.duration > self.workorder_id.duration_expected:
        self.loss_id = self.env.ref("mrp.block_reason4").id
    else:
        self.loss_id = self.env.ref("mrp.block_reason7").id

def _close(self):
    underperformance_timers = self.env['mrp.workcenter.productivity']
    for timer in self:
        wo = timer.workorder_id
        timer.write({'date_end': fields.Datetime.now()})
        if wo.duration > wo.duration_expected:
            productive_date_end = timer.date_end - relativedelta.relativedelta(minutes=wo.duration - wo.duration_expected)
            if productive_date_end <= timer.date_start:
                underperformance_timers |= timer
            else:
                underperformance_timers |= timer.copy({'date_start': productive_date_end})
                timer.write({'date_end': productive_date_end})
    if underperformance_timers:
        underperformance_type = self.env['mrp.workcenter.productivity.loss'].search([('loss_type', '=', 'performance')], limit=1)
        if not underperformance_type:
            raise UserError(_("You need to define at least one unactive productivity loss in the category 'Performance'. Create one from the Manufacturing app, menu: Configuration / Productivity Losses."))
        underperformance_timers.write({'loss_id': underperformance_type.id})

def _default_time_start(self):
    workcenter_id = self.env.context.get('default_workcenter_id')
    return self.env['mrp.workcenter'].browse(workcenter_id).time_start if workcenter_id else 0.0

def _default_time_stop(self):
    workcenter_id = self.env.context.get('default_workcenter_id')
    return self.env['mrp.workcenter'].browse(workcenter_id).time_stop if workcenter_id else 0.0

def _compute_uom_id(self):
    for capacity in self:
        capacity.uom_id = capacity.product_id.uom_id or self.env.ref('uom.product_uom_unit')

def _check_stock_quantity(cls, sales):
    for sale in sales:
        sale.check_stock_quantity()

def _stock_quantity_next_supply_date(cls, product):
    pool = Pool()
    try:
        PurchaseRequest = pool.get('purchase.request')
    except KeyError:
        PurchaseRequest = None

    if (getattr(PurchaseRequest, 'get_supply_dates', None)
            and product.purchasable):
        return PurchaseRequest.get_supply_dates(product)[0]
    else:
        # TODO compute supply date for production
        return datetime.date.max

def create_productions(self, product_quantities):
    productions = []
    for line in self.lines:
        production = line.get_production(product_quantities)
        if not production:
            continue
        production.set_planned_start_date()
        productions.append(production)
        assert not line.productions
    return productions

def get_supply_state(self, name):
    state = super().get_supply_state(name)
    if self.productions:
        states = {p.state for p in self.productions}
        if states <= {'running', 'done', 'cancelled'}:
            if states == {'cancelled'}:
                state = 'cancelled'
            else:
                state = 'supplied'
        else:
            state = 'requested'
    return state

def copy(cls, lines, default=None):
    if default is None:
        default = {}
    else:
        default = default.copy()
    default.setdefault('productions', None)
    return super().copy(lines, default=default)

def get_production(self, product_quantities, bom_pattern=None):
    production = super().get_production(
        product_quantities, bom_pattern=bom_pattern)
    if production and production.product:
        if pbom := production.product.get_bom(bom_pattern):
            production.routing = pbom.routing
    return production

@Override
@Transactional(rollbackOn = {Exception.class})
public void updateLocation(
    StockLocation stockLocation,
    Product product,
    Unit stockMoveLineUnit,
    BigDecimal qty,
    boolean current,
    boolean future,
    boolean isIncrement,
    LocalDate lastFutureStockMoveDate,
    boolean generateOrder)
    throws AxelorException {

  StockLocationLine stockLocationLine = this.getOrCreateStockLocationLine(stockLocation, product);

  if (stockLocationLine == null) {
    return;
  }

  Unit stockLocationLineUnit = stockLocationLine.getUnit();
  if (stockLocationLineUnit == null) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.LOCATION_LINE_MISSING_UNIT),
        stockLocation.getName(),
        product.getFullName());
  }
  if (!stockLocationLineUnit.equals(stockMoveLineUnit)) {
    qty =
        unitConversionService.convert(
            stockMoveLineUnit, stockLocationLineUnit, qty, qty.scale(), product);
  }

  LOG.debug(
      "Stock update : Stock location? {}, Product? {}, Quantity? {}, Current quantity? {}, Future quantity? {}, Is increment? {}, Date? {} ",
      stockLocation.getName(),
      product.getCode(),
      qty,
      current,
      future,
      isIncrement,
      lastFutureStockMoveDate);

  if (generateOrder && isIncrement) {
    maxStockRules(product, qty, stockLocationLine, current, future);
  }

  stockLocationLine =
      this.updateLocation(
          stockLocationLine,
          stockMoveLineUnit,
          product,
          qty,
          current,
          future,
          isIncrement,
          lastFutureStockMoveDate);

  this.checkStockMin(stockLocationLine, false);

  stockLocationLineRepo.save(stockLocationLine);
}

@Override
public void maxStockRules(
    Product product,
    BigDecimal qty,
    StockLocationLine stockLocationLine,
    boolean current,
    boolean future)
    throws AxelorException {

  if (current) {
    checkStockMax(
        product,
        qty,
        stockLocationLine,
        StockRulesRepository.TYPE_CURRENT,
        stockLocationLine.getCurrentQty());
  }

  if (future) {
    checkStockMax(
        product,
        qty,
        stockLocationLine,
        StockRulesRepository.TYPE_FUTURE,
        stockLocationLine.getFutureQty());
  }
}

protected void checkStockMax(
    Product product,
    BigDecimal qty,
    StockLocationLine stockLocationLine,
    int type,
    BigDecimal baseQty)
    throws AxelorException {
  StockLocation stockLocation = stockLocationLine.getStockLocation();
  StockRules stockRules =
      stockRulesService.getStockRules(
          product, stockLocation, type, StockRulesRepository.USE_CASE_STOCK_CONTROL);

  if (stockRules == null || !stockRules.getUseMaxQty()) {
    return;
  }

  if (baseQty.add(qty).compareTo(stockRules.getMaxQty()) > 0) {
    throw new AxelorException(
        stockLocationLine,
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.LOCATION_LINE_3),
        stockLocationLine.getProduct().getName(),
        stockLocationLine.getProduct().getCode());
  }
}

