@Transactional(rollbackOn = {Exception.class})
protected void generatePurchaseProposal(
    MrpLine mrpLine,
    Map<Pair<Partner, LocalDate>, PurchaseOrder> purchaseOrders,
    Map<Partner, PurchaseOrder> purchaseOrdersPerSupplier,
    boolean isProposalsPerSupplier)
    throws AxelorException {

  Product product = mrpLine.getProduct();
  StockLocation stockLocation = mrpLine.getStockLocation();
  LocalDate maturityDate = mrpLine.getMaturityDate();

  Partner supplierPartner = mrpLine.getSupplierPartner();

  if (supplierPartner == null) {
    supplierPartner = product.getDefaultSupplierPartner();

    if (supplierPartner == null) {
      throw new AxelorException(
          mrpLine,
          TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
          I18n.get(SupplychainExceptionMessage.MRP_LINE_1),
          product.getFullName());
    }
  }

  Company company = stockLocation.getCompany();

  Pair<Partner, LocalDate> key = null;
  PurchaseOrder purchaseOrder = null;

  if (isProposalsPerSupplier) {
    if (purchaseOrdersPerSupplier != null && !purchaseOrdersPerSupplier.isEmpty()) {
      purchaseOrder = purchaseOrdersPerSupplier.get(supplierPartner);
      if (purchaseOrder != null) {
        purchaseOrder = purchaseOrderRepo.find(purchaseOrder.getId());
      }
    }
  } else {
    if (purchaseOrders != null) {
      key = Pair.of(supplierPartner, maturityDate);
      purchaseOrder = purchaseOrders.get(key);
    }
  }

  if (purchaseOrder == null) {
    purchaseOrder =
        purchaseOrderRepo.save(
            purchaseOrderCreateSupplychainService.createPurchaseOrder(
                AuthUtils.getUser(),
                company,
                null,
                supplierPartner.getCurrency(),
                null,
                this.getPurchaseOrderOrigin(mrpLine),
                null,
                stockLocation,
                appBaseService.getTodayDate(company),
                Beans.get(PartnerPriceListService.class)
                    .getDefaultPriceList(supplierPartner, PriceListRepository.TYPE_PURCHASE),
                supplierPartner,
                null,
                supplierPartner.getFiscalPosition()));
    if (isProposalsPerSupplier) {
      if (purchaseOrdersPerSupplier != null) {
        purchaseOrdersPerSupplier.put(supplierPartner, purchaseOrder);
      }
    } else {
      if (purchaseOrders != null) {
        purchaseOrders.put(key, purchaseOrder);
      }
    }
    if (mrpLine.getMrpLineOriginList().size() == 1) {
      if (mrpLine
          .getMrpLineOriginList()
          .get(0)
          .getRelatedToSelect()
          .equals(MrpLineOriginRepository.RELATED_TO_SALE_ORDER_LINE)) {
        purchaseOrder.setGeneratedSaleOrderId(
            saleOrderLineRepo
                .find(mrpLine.getMrpLineOriginList().get(0).getRelatedToSelectId())
                .getSaleOrder()
                .getId());
      }
    }
  }
  Unit unit = product.getPurchasesUnit();
  BigDecimal qty = mrpLine.getQty();
  if (unit == null) {
    unit = product.getUnit();
  } else {
    qty =
        Beans.get(UnitConversionService.class)
            .convert(product.getUnit(), unit, qty, qty.scale(), product);
  }
  purchaseOrder.setNotes(supplierPartner.getPurchaseOrderComments());
  LocalDate desiredReceiptDate = maturityDate;
  if (mrpLine.getEstimatedDeliveryMrpLine() != null) {
    desiredReceiptDate = mrpLine.getEstimatedDeliveryMrpLine().getMaturityDate();
  }

  PurchaseOrderLine poLine =
      createOrUpdatePurchaseOrderLine(purchaseOrder, product, unit, qty, desiredReceiptDate);

  purchaseOrderLineService.compute(poLine, purchaseOrder);

  purchaseOrderService.computePurchaseOrder(purchaseOrder);

  linkToOrder(mrpLine, purchaseOrder);
}

protected PurchaseOrderLine createOrUpdatePurchaseOrderLine(
    PurchaseOrder purchaseOrder,
    Product product,
    Unit unit,
    BigDecimal qty,
    LocalDate desiredReceiptDate)
    throws AxelorException {
  PurchaseOrderLine poLine =
      findMatchingPurchaseOrderLine(purchaseOrder, product, unit, desiredReceiptDate);
  if (poLine != null) {
    poLine.setQty(poLine.getQty().add(qty));
    return poLine;
  }

  poLine =
      purchaseOrderLineService.createPurchaseOrderLine(
          purchaseOrder, product, null, null, qty, unit);
  poLine.setDesiredReceiptDate(desiredReceiptDate);
  poLine.setEstimatedReceiptDate(desiredReceiptDate);
  purchaseOrder.addPurchaseOrderLineListItem(poLine);
  return poLine;
}

protected PurchaseOrderLine findMatchingPurchaseOrderLine(
    PurchaseOrder purchaseOrder, Product product, Unit unit, LocalDate desiredReceiptDate) {
  if (purchaseOrder.getPurchaseOrderLineList() == null) {
    return null;
  }

  return purchaseOrder.getPurchaseOrderLineList().stream()
      .filter(Objects::nonNull)
      .filter(purchaseOrderLine -> product.equals(purchaseOrderLine.getProduct()))
      .filter(purchaseOrderLine -> Objects.equals(unit, purchaseOrderLine.getUnit()))
      .filter(
          purchaseOrderLine ->
              Objects.equals(desiredReceiptDate, purchaseOrderLine.getDesiredReceiptDate()))
      .findFirst()
      .orElse(null);
}

protected String getPurchaseOrderOrigin(MrpLine mrpLine) {
  StringBuilder origin = new StringBuilder();
  int count = 0;
  for (MrpLineOrigin mrpLineOrigin : mrpLine.getMrpLineOriginList()) {
    count++;
    origin.append(getMrpLineOriginStr(mrpLineOrigin));
    if (count < mrpLine.getMrpLineOriginList().size()) {
      origin.append(" & ");
    }
  }
  return origin.toString();
}

protected String getMrpLineOriginStr(MrpLineOrigin mrpLineOrigin) {
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_SALE_ORDER_LINE)) {
    SaleOrder saleOrder =
        saleOrderLineRepo.find(mrpLineOrigin.getRelatedToSelectId()).getSaleOrder();
    return saleOrder.getSaleOrderSeq();
  }
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_PURCHASE_ORDER_LINE)) {
    PurchaseOrder purchaseOrder =
        purchaseOrderLineRepo.find(mrpLineOrigin.getRelatedToSelectId()).getPurchaseOrder();
    return purchaseOrder.getPurchaseOrderSeq();
  }
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_MRP_FORECAST)) {
    return mrpLineOrigin.getMrpLine().getMrp().getMrpSeq() + "-" + I18n.get("MRP forecast");
  }
  return "";
}

protected void linkToOrder(MrpLine mrpLine, AuditableModel order) {
  mrpLine.setProposalSelect(order.getClass().getName());
  mrpLine.setProposalSelectId(order.getId());
  mrpLine.setProposalGenerated(true);
}

public MrpLine createMrpLine(
    Mrp mrp,
    Product product,
    int maxLevel,
    MrpLineType mrpLineType,
    BigDecimal qty,
    LocalDate maturityDate,
    BigDecimal cumulativeQty,
    StockLocation stockLocation,
    Model model) {

  MrpLine mrpLine = new MrpLine();

  mrpLine.setMrp(mrp);
  mrpLine.setProduct(product);
  mrpLine.setMaxLevel(maxLevel);
  mrpLine.setMrpLineType(mrpLineType);
  if (mrpLineType.getTypeSelect() == MrpLineTypeRepository.TYPE_OUT) {
    mrpLine.setQty(qty.negate());
  } else {
    mrpLine.setQty(qty);
  }
  mrpLine.setMaturityDate(maturityDate);
  mrpLine.setCumulativeQty(cumulativeQty);
  mrpLine.setStockLocation(stockLocation);

  mrpLine = this.setMrpLineQty(mrpLine, product, stockLocation);

  if (mrpLineType.getElementSelect() == MrpLineTypeRepository.ELEMENT_PURCHASE_PROPOSAL) {
    mrpLine.setSupplierPartner(product.getDefaultSupplierPartner());
  }

  this.updatePartner(mrpLine, model);

  this.createMrpLineOrigins(mrpLine, model);

  log.debug(
      "Create mrp line for the product {}, level {}, mrpLineType {}, qty {}, maturity date {}, cumulative qty {}, stock location {}, related to {}",
      product.getCode(),
      maxLevel,
      mrpLineType.getCode(),
      qty,
      maturityDate,
      cumulativeQty,
      stockLocation.getName(),
      mrpLine.getRelatedToSelectName());

  return mrpLine;
}

protected MrpLine setMrpLineQty(MrpLine mrpLine, Product product, StockLocation stockLocation) {

  StockRules stockRules =
      stockRulesService.getStockRules(
          product,
          stockLocation,
          StockRulesRepository.TYPE_FUTURE,
          StockRulesRepository.USE_CASE_USED_FOR_MRP);

  if (stockRules != null) {
    mrpLine.setMinQty(stockRules.getMinQty());
    mrpLine.setIdealQty(stockRules.getIdealQty());
    mrpLine.setReOrderQty(stockRules.getReOrderQty());
  }
  return mrpLine;
}

protected void createMrpLineOrigins(MrpLine mrpLine, Model model) {

  if (model != null) {

    mrpLine.addMrpLineOriginListItem(this.createMrpLineOrigin(model));
    mrpLine.setRelatedToSelectName(this.computeRelatedName(model));
  }
}

public MrpLineOrigin createMrpLineOrigin(Model model) {

  Class<?> klass = EntityHelper.getEntityClass(model);

  MrpLineOrigin mrpLineOrigin = new MrpLineOrigin();
  mrpLineOrigin.setRelatedToSelect(klass.getCanonicalName());
  mrpLineOrigin.setRelatedToSelectId(model.getId());

  return mrpLineOrigin;
}

public MrpLineOrigin copyMrpLineOrigin(MrpLineOrigin mrpLineOrigin) {

  MrpLineOrigin copyMrpLineOrigin = new MrpLineOrigin();
  copyMrpLineOrigin.setRelatedToSelect(mrpLineOrigin.getRelatedToSelect());
  copyMrpLineOrigin.setRelatedToSelectId(mrpLineOrigin.getRelatedToSelectId());

  return copyMrpLineOrigin;
}

@Override
public void updateProposalToProcess(List<Integer> mrpLineIds, boolean proposalToProcess) {
  MrpLine mrpLine;
  for (Integer mrpId : mrpLineIds) {
    mrpLine = mrpLineRepo.find(Long.valueOf(mrpId));

    updateProposalToProcess(mrpLine, proposalToProcess);
  }
}

protected String computeRelatedName(Model model) {

  if (model instanceof SaleOrderLine) {

    return ((SaleOrderLine) model).getSaleOrder().getSaleOrderSeq();

  } else if (model instanceof PurchaseOrderLine) {

    return ((PurchaseOrderLine) model).getPurchaseOrder().getPurchaseOrderSeq();

  } else if (model instanceof MrpForecast) {

    MrpForecast mrpForecast = (MrpForecast) model;
    return mrpForecast.getId() + "-" + mrpForecast.getForecastDate();
  }
  return null;
}

protected void updatePartner(MrpLine mrpLine, Model model) {

  if (model != null) {
    mrpLine.setPartner(this.getPartner(model));
  }
}

protected Partner getPartner(Model model) {

  if (model instanceof SaleOrderLine) {

    return ((SaleOrderLine) model).getSaleOrder().getClientPartner();

  } else if (model instanceof PurchaseOrderLine) {

    return ((PurchaseOrderLine) model).getPurchaseOrder().getSupplierPartner();

  } else if (model instanceof MrpForecast) {

    return ((MrpForecast) model).getPartner();
  }
  return null;
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void updateProposalToProcess(MrpLine mrpLine, boolean proposalToProcess) {
  if (!mrpLine.getProposalGenerated()
      && (mrpLine.getMrpLineType().getElementSelect()
              == MrpLineTypeRepository.ELEMENT_PURCHASE_PROPOSAL
          || mrpLine.getMrpLineType().getElementSelect()
              == MrpLineTypeRepository.ELEMENT_MANUFACTURING_PROPOSAL)) {
    mrpLine.setProposalToProcess(proposalToProcess);
    mrpLineRepo.save(mrpLine);
  }
}

@Override
public List<MrpLine> getMrpLineListCopy(List<MrpLine> mrpLineList) {
  List<MrpLine> copyMrpLineList = new ArrayList<>();
  mrpLineList =
      mrpLineRepo.findByIds(
          mrpLineList.stream().map(MrpLine::getId).collect(Collectors.toList()));
  for (MrpLine mrpLine : mrpLineList) {
    copyMrpLineList.add(mrpLineRepo.copy(mrpLine, true));
  }

  return copyMrpLineList;
}

@Override
public void computeMarginSaleOrder(SaleOrder saleOrder) {
  super.computeMarginSaleOrder(saleOrder);
  saleOrder.setTotalCostPrice(saleOrder.getTotalCostPrice().add(saleOrder.getShippingCost()));
}

def _preprocess_ctx(ctx):
	if not ctx.price_list:
		ctx.price_list = ctx.selling_price_list or ctx.buying_price_list

	if not ctx.item_code and ctx.barcode:
		ctx.item_code = get_item_code(barcode=ctx.barcode)
	elif not ctx.item_code and ctx.serial_no:
		ctx.item_code = get_item_code(serial_no=ctx.serial_no)

	set_transaction_type(ctx)

def get_item_details(
	ctx: ItemDetailsCtx,
	doc: Document | str | dict | None = None,
	for_validate: bool | None = False,
	overwrite_warehouse: bool = True,
) -> ItemDetails:
	validate_pricing_context(ctx)
	return _get_item_details(ctx, doc, for_validate, overwrite_warehouse)

def remove_standard_fields(out: ItemDetails):
	for key in child_table_fields + default_fields:
		out.pop(key, None)
	return out

def get_rate_locked_source_row(ctx: ItemDetailsCtx, doc) -> frappe._dict | None:
	"""Return the persisted source-document row a mapped target row is locked to.

	The rate is read from the linked source row in the database (not the mutable
	target row), so a re-fetch always restores the source pricing the maintain-same-
	rate validator checks against, even after an unsaved edit on the target row.
	"""
	if isinstance(doc, str):
		doc = json.loads(doc)

	source_fields = maintain_same_rate_source_fields.get(ctx.parenttype or ctx.doctype)
	if not source_fields or not doc or ctx.get("is_return") or not maintain_same_rate_enabled(ctx):
		return None

	row = (
		next((d for d in doc.get("items") or [] if d.get("name") == ctx.child_docname), None)
		if ctx.child_docname
		else ctx
	)
	if not row:
		return None

	for link_field, source_doctype in source_fields.items():
		if source_name := row.get(link_field):
			# a direct read would bypass permissions; only return source pricing to a
			# caller allowed to read the source document
			source = frappe.db.get_value(
				source_doctype, source_name, [*LOCKED_RATE_FIELDS, "parent", "parenttype"], as_dict=True
			)
			if source and has_source_doc_permission(source.parenttype, source.parent, frappe.session.user):
				return source
			return None
	return None

def maintain_same_rate_enabled(ctx: ItemDetailsCtx) -> bool:
	if (ctx.parenttype or ctx.doctype) in purchase_doctypes:
		if ctx.get("is_internal_supplier"):
			return False
		return bool(cint(frappe.get_cached_value("Buying Settings", "None", "maintain_same_rate")))

	if ctx.get("is_internal_customer"):
		return False
	return bool(cint(frappe.get_cached_value("Selling Settings", "None", "maintain_same_sales_rate")))

def set_valuation_rate(out: ItemDetails | dict, ctx: ItemDetailsCtx):
	if frappe.db.exists("Product Bundle", {"name": ctx.item_code, "disabled": 0}, cache=True):
		valuation_rate = 0.0
		bundled_items = frappe.get_doc("Product Bundle", ctx.item_code)

		for bundle_item in bundled_items.items:
			valuation_rate += flt(
				_get_valuation_rate(bundle_item.item_code, ctx.company, out.get("warehouse")).get(
					"valuation_rate"
				)
				* bundle_item.qty
			)

		out.update({"valuation_rate": valuation_rate})

	else:
		out.update(_get_valuation_rate(ctx.item_code, ctx.company, out.get("warehouse")))

def update_stock(ctx, out, doc=None):
	from erpnext.stock.doctype.batch.batch import get_available_batches

	if (
		(
			ctx.get("doctype") in ["Delivery Note", "POS Invoice"]
			or (ctx.get("doctype") == "Sales Invoice" and ctx.get("update_stock"))
		)
		and out.warehouse
		and out.stock_qty > 0
	):
		if doc and isinstance(doc, dict):
			doc = frappe._dict(doc)

		kwargs = frappe._dict(
			{
				"item_code": ctx.item_code,
				"warehouse": ctx.warehouse,
				"based_on": frappe.get_single_value("Stock Settings", "pick_serial_and_batch_based_on"),
				"sabb_voucher_no": doc.get("name") if doc else None,
				"sabb_voucher_detail_no": ctx.child_docname,
				"sabb_voucher_type": ctx.doctype,
				"pick_reserved_items": True,
				"qty": out.stock_qty,
			}
		)

		if ctx.get("doctype") == "Delivery Note":
			kwargs["against_sales_order"] = ctx.get("against_sales_order")

		if ctx.get("ignore_serial_nos"):
			kwargs["ignore_serial_nos"] = ctx.get("ignore_serial_nos")

		qty = out.stock_qty
		batches = []
		if out.has_batch_no and not ctx.get("batch_no"):
			batches = get_available_batches(kwargs)
			if doc:
				filter_batches(batches, doc)

			for batch_no, batch_qty in batches.items():
				rate = _get_batch_based_item_price(
					{"price_list": doc.get("selling_price_list"), "uom": out.uom, "batch_no": batch_no},
					out.item_code,
				)
				if batch_qty >= qty:
					out.update({"batch_no": batch_no, "actual_batch_qty": qty})
					if rate:
						out.update({"rate": rate, "price_list_rate": rate})
					break
				else:
					qty -= batch_qty

				out.update({"batch_no": batch_no, "actual_batch_qty": batch_qty})
				if rate:
					out.update({"rate": rate, "price_list_rate": rate})

		if out.has_serial_no and needs_serial_nos(ctx, out):
			set_serial_nos_for_outward(ctx, out, kwargs, doc)

def needs_serial_nos(ctx, out):
	if not out.has_batch_no:
		return not ctx.get("serial_no")

	if ctx.get("use_serial_batch_fields"):
		return False

	return has_incorrect_serial_nos(ctx, out)

def set_serial_nos_for_outward(ctx, out, kwargs, doc):
	from erpnext.stock.doctype.serial_no.serial_no import get_serial_nos_for_outward

	if out.has_batch_no:
		kwargs["batches"] = [ctx.get("batch_no") or out.get("batch_no")]

	serial_nos = get_filtered_serial_nos(get_serial_nos_for_outward(kwargs), doc)
	out["serial_no"] = "\n".join(serial_nos[: cint(out.stock_qty)])

def has_incorrect_serial_nos(ctx, out):
	from erpnext.stock.doctype.serial_no.serial_no import get_serial_nos

	if not ctx.get("serial_no"):
		return True

	serial_nos = get_serial_nos(ctx.get("serial_no"))
	if len(serial_nos) != out.get("stock_qty"):
		return True

	return False

def filter_batches(batches, doc):
	for row in doc.get("items"):
		if row.get("batch_no") in batches:
			batches[row.get("batch_no")] -= row.get("qty")
			if batches[row.get("batch_no")] <= 0:
				del batches[row.get("batch_no")]

def get_filtered_serial_nos(serial_nos, doc, table=None):
	from erpnext.stock.doctype.serial_no.serial_no import get_serial_nos

	if not table:
		table = "items"

	for row in doc.get(table):
		if row.get("serial_no"):
			for serial_no in get_serial_nos(row.get("serial_no")):
				if serial_no in serial_nos:
					serial_nos.remove(serial_no)

	return serial_nos

def update_bin_details(ctx: ItemDetailsCtx, out: ItemDetails, doc):
	if ctx.doctype == "Material Request" and ctx.material_request_type == "Material Transfer":
		out.update(get_bin_details(ctx.item_code, ctx.from_warehouse))

	elif out.get("warehouse"):
		bin_details = get_bin_details(
			ctx.item_code, out.warehouse, ctx.company, include_child_warehouses=True
		)

		out.update(bin_details)

def get_item_code(barcode=None, serial_no=None):
	if barcode:
		item_code = frappe.db.get_value("Item Barcode", {"barcode": barcode}, fieldname=["parent"])
		if not item_code:
			frappe.throw(_("No Item with Barcode {0}").format(barcode))
	elif serial_no:
		item_code = frappe.db.get_value("Serial No", serial_no, "item_code")
		if not item_code:
			frappe.throw(_("No Item with Serial No {0}").format(serial_no))

	return item_code

def validate_item_details(ctx: ItemDetailsCtx, item):
	if not ctx.company:
		throw(_("Please specify Company"))

	from erpnext.stock.doctype.item.item import validate_end_of_life

	validate_end_of_life(item.name, item.end_of_life, item.disabled)

	if cint(item.has_variants):
		msg = f"Item {item.name} is a template, please select one of its variants"

		throw(_(msg), title=_("Template Item Selected"))

	elif ctx.doctype != "Material Request":
		if ctx.is_subcontracted:
			if ctx.is_old_subcontracting_flow:
				if item.is_sub_contracted_item != 1:
					throw(_("Item {0} must be a Sub-contracted Item").format(item.name))
			else:
				if item.is_stock_item:
					throw(_("Item {0} must be a Non-Stock Item").format(item.name))

def get_item_warehouse_(ctx: ItemDetailsCtx, item, overwrite_warehouse, defaults=None):
	if not defaults:
		defaults = frappe._dict(
			{
				"item_defaults": get_item_defaults(item.name, ctx.company),
				"item_group_defaults": get_item_group_defaults(item.name, ctx.company),
				"brand_defaults": get_brand_defaults(item.name, ctx.company),
			}
		)

	if overwrite_warehouse or not ctx.warehouse:
		warehouse = (
			ctx.set_warehouse
			or defaults.item_defaults.get("default_warehouse")
			or defaults.item_group_defaults.get("default_warehouse")
			or defaults.brand_defaults.get("default_warehouse")
			or ctx.warehouse
		)

	else:
		warehouse = ctx.warehouse

	if not warehouse and ctx.company:
		return frappe.get_cached_value("Company", ctx.company, "default_warehouse")

	return warehouse

def update_barcode_value(out):
	barcode_data = get_barcode_data([out])

	# If item has one barcode then update the value of the barcode field
	if barcode_data and len(barcode_data.get(out.item_code)) == 1:
		out["barcode"] = barcode_data.get(out.item_code)[0]

def get_barcode_data(items_list=None, item_code=None):
	# get item-wise batch no data
	# example: {'LED-GRE': [Batch001, Batch002]}
	# where LED-GRE is item code, SN0001 is serial no and Pune is warehouse

	itemwise_barcode = {}
	if not items_list and item_code:
		_dict_item_code = frappe._dict(
			{
				"item_code": item_code,
			}
		)

		items_list = [frappe._dict(_dict_item_code)]

	for item in items_list:
		barcodes = frappe.db.get_all("Item Barcode", filters={"parent": item.item_code}, fields="barcode")

		for barcode in barcodes:
			if item.item_code not in itemwise_barcode:
				itemwise_barcode.setdefault(item.item_code, [])
			itemwise_barcode[item.item_code].append(barcode.get("barcode"))

	return itemwise_barcode

def get_item_tax_info(doc, tax_category, item_codes, item_rates=None, item_tax_templates=None):
	out = {}

	if item_tax_templates is None:
		item_tax_templates = {}

	if item_rates is None:
		item_rates = {}

	doc = parse_json(doc)
	item_codes = parse_json(item_codes)
	item_rates = parse_json(item_rates)
	item_tax_templates = parse_json(item_tax_templates)

	for item_code in item_codes:
		if not item_code or item_code[1] in out or not item_tax_templates.get(item_code[1]):
			continue

		out[item_code[1]] = ItemDetails()
		item = frappe.get_cached_doc("Item", item_code[0])
		ctx: ItemDetailsCtx = {
			"company": doc.company,
			"tax_category": tax_category,
			"base_net_rate": item_rates.get(item_code[1]),
		}

		if item_tax_templates:
			ctx.update({"item_tax_template": item_tax_templates.get(item_code[1])})

		get_item_tax_template(ctx, item, out[item_code[1]])
		out[item_code[1]]["item_tax_rate"] = get_item_tax_map(
			doc=doc,
			tax_template=out[item_code[1]].get("item_tax_template"),
			as_json=True,
		)

	return out

def get_item_tax_template(ctx, item=None, out: ItemDetails | None = None):
	"""
	Determines item_tax template from item or parent item groups.

	Accesses:
	        ctx = {
	        "child_doctype": str
	        }
	Passes:
	        ctx = {
	                "company": str
	                "bill_date": str
	                "transaction_date": str
	        "tax_category": None
	        "item_tax_template": None
	        "base_net_rate": float
	        }
	"""
	if not item:
		if not ctx.get("item_code"):
			frappe.throw(_("Item/Item Code required to get Item Tax Template."))
		else:
			item = frappe.get_cached_doc("Item", ctx.item_code)

	item_tax_template = None
	if item.taxes:
		item_tax_template = _get_item_tax_template(ctx, item.taxes, out)

	if not item_tax_template:
		item_tax_template = _get_item_tax_template_from_item_group(ctx, item.item_group, out)

	if out and ctx.get("child_doctype") and item_tax_template:
		out.update(get_fetch_values(ctx.get("child_doctype"), "item_tax_template", item_tax_template))

	return item_tax_template

def _get_item_tax_template_from_item_group(ctx, item_group, out=None):
	from frappe.utils.nestedset import get_ancestors_of

	ancestors = get_ancestors_of("Item Group", item_group)
	for group in [item_group, *ancestors]:
		group_doc = frappe.get_cached_doc("Item Group", group)
		item_tax_template = _get_item_tax_template(ctx, group_doc.taxes, out)
		if item_tax_template:
			return item_tax_template
	return None

def _get_item_tax_template(
	ctx: ItemDetailsCtx, taxes, out: ItemDetails | None = None, for_validate=False
) -> None | str | list[str]:
	"""
	Accesses:
	        ctx = {
	                "company": str
	                "bill_date": str
	                "transaction_date": str
	        "tax_category": None
	        "item_tax_template": None
	        }
	Passes:
	        ctx = {
	        "base_net_rate": float
	        }
	"""
	if out is None:
		out = ItemDetails()
	taxes_with_validity = []
	taxes_with_no_validity = []

	for tax in taxes:
		disabled, tax_company = frappe.get_cached_value(
			"Item Tax Template", tax.item_tax_template, ["disabled", "company"]
		)
		if not disabled and tax_company == ctx["company"]:
			if tax.valid_from or tax.maximum_net_rate:
				# In purchase Invoice first preference will be given to supplier invoice date
				# if supplier date is not present then posting date
				validation_date = (
					ctx.get("bill_date") or ctx.get("posting_date") or ctx.get("transaction_date")
				)

				if getdate(tax.valid_from) <= getdate(validation_date) and is_within_valid_range(ctx, tax):
					taxes_with_validity.append(tax)
			else:
				taxes_with_no_validity.append(tax)

	if taxes_with_validity:
		taxes = sorted(taxes_with_validity, key=lambda i: i.valid_from or tax.maximum_net_rate, reverse=True)
	else:
		taxes = taxes_with_no_validity

	if for_validate:
		return [
			tax.item_tax_template
			for tax in taxes
			if (
				cstr(tax.tax_category) == cstr(ctx.get("tax_category"))
				and (tax.item_tax_template not in taxes)
			)
		]

	# all templates have validity and no template is valid
	if not taxes_with_validity and (not taxes_with_no_validity):
		return None

	# do not change if already a valid template
	if ctx.get("item_tax_template") in {t.item_tax_template for t in taxes}:
		out.item_tax_template = ctx.get("item_tax_template")
		return ctx.get("item_tax_template")

	for tax in taxes:
		if cstr(tax.tax_category) == cstr(ctx.get("tax_category")):
			out.item_tax_template = tax.item_tax_template
			return tax.item_tax_template
	return None

def is_within_valid_range(ctx: ItemDetailsCtx, tax) -> bool:
	"""
	Accesses:
	        ctx = {
	        "base_net_rate": float
	        }
	"""

	if not flt(tax.maximum_net_rate):
		# No range specified, just ignore
		return True
	elif flt(tax.minimum_net_rate) <= flt(ctx.get("base_net_rate")) <= flt(tax.maximum_net_rate):
		return True

	return False

def get_item_tax_map(*, doc: str | dict | Document, tax_template: str | None = None, as_json=True):
	doc = parse_json(doc)
	item_tax_map = {}
	for t in (t for t in (doc.get("taxes") or []) if not t.get("set_by_item_tax_template")):
		item_tax_map[t.get("account_head")] = t.get("rate")

	if tax_template:
		template = frappe.get_cached_doc("Item Tax Template", tax_template)
		for d in template.taxes:
			if frappe.get_cached_value("Account", d.tax_type, "company") == doc.get("company"):
				if d.get("not_applicable"):
					item_tax_map[d.tax_type] = NOT_APPLICABLE_TAX
				else:
					item_tax_map[d.tax_type] = d.tax_rate

	return json.dumps(item_tax_map) if as_json else item_tax_map

