def get_default_cost_center(ctx: ItemDetailsCtx, item=None, item_group=None, brand=None, company=None):
	cost_center = None

	if not company and ctx.get("company"):
		company = ctx.get("company")

	if ctx.get("project"):
		cost_center = frappe.db.get_value("Project", ctx.get("project"), "cost_center", cache=True)

	if not cost_center and (item and item_group and brand):
		if ctx.get("customer"):
			cost_center = (
				item.get("selling_cost_center")
				or item_group.get("selling_cost_center")
				or brand.get("selling_cost_center")
			)
		else:
			cost_center = (
				item.get("buying_cost_center")
				or item_group.get("buying_cost_center")
				or brand.get("buying_cost_center")
			)

	elif not cost_center and ctx.get("item_code") and company:
		for method in ["get_item_defaults", "get_item_group_defaults", "get_brand_defaults"]:
			path = f"erpnext.stock.get_item_details.{method}"
			data = frappe.get_attr(path)(ctx.get("item_code"), company)

			if data and (data.selling_cost_center or data.buying_cost_center):
				if ctx.get("customer") and data.selling_cost_center:
					return data.selling_cost_center

				elif ctx.get("supplier") and data.buying_cost_center:
					return data.buying_cost_center

				return data.selling_cost_center or data.buying_cost_center

	if not cost_center and ctx.get("cost_center"):
		cost_center = ctx.get("cost_center")

	if company and cost_center and frappe.get_cached_value("Cost Center", cost_center, "company") != company:
		return None

	if not cost_center and company:
		cost_center = frappe.get_cached_value("Company", company, "cost_center")

	return cost_center

def get_price_list_rate(ctx: ItemDetailsCtx, item_doc, out: ItemDetails = None):
	if out is None:
		out = ItemDetails()

	meta = frappe.get_meta(ctx.parenttype or ctx.doctype)

	if meta.get_field("currency") or ctx.get("currency"):
		if not ctx.price_list_currency or not ctx.plc_conversion_rate:
			# if currency and plc_conversion_rate exist then
			# `get_price_list_currency_and_exchange_rate` has already been called
			pl_details = get_price_list_currency_and_exchange_rate(ctx)
			ctx.update(pl_details)

		if meta.get_field("currency"):
			validate_conversion_rate(ctx, meta)

		price_list_rate = get_price_list_rate_for(ctx, item_doc.name)

		# variant
		if price_list_rate is None and item_doc.variant_of:
			price_list_rate = get_price_list_rate_for(ctx, item_doc.variant_of)

		# insert in database
		if price_list_rate is None or frappe.get_cached_value(
			"Stock Settings", "Stock Settings", "update_existing_price_list_rate"
		):
			insert_item_price(ctx)

		if price_list_rate is None:
			return out

		out.price_list_rate = flt(price_list_rate) * flt(ctx.plc_conversion_rate) / flt(ctx.conversion_rate)

		if frappe.db.get_single_value("Buying Settings", "disable_last_purchase_rate"):
			return out

		if not ctx.is_internal_supplier and not out.price_list_rate and ctx.transaction_type == "buying":
			from erpnext.stock.doctype.item.item import get_last_purchase_details

			out.update(get_last_purchase_details(item_doc.name, ctx.name, ctx.conversion_rate))

	return out

def get_item_prices_to_auto_update(ctx):
	ip = frappe.qb.DocType("Item Price")
	query = (
		frappe.qb.from_(ip)
		.select(ip.name, ip.price_list_rate, ip.valid_from, ip.valid_upto)
		.where(
			(ip.item_code == ctx.item_code)
			& (ip.price_list == ctx.price_list)
			& (ip.currency == ctx.currency)
			& (ip.uom == ctx.stock_uom)
		)
	)

	for fieldname in ("customer", "supplier", "batch_no"):
		query = query.where(IfNull(ip[fieldname], "").isin(["", cstr(ctx.get(fieldname))]))
		query = query.orderby(IfNull(ip[fieldname], ""), order=frappe.qb.desc)

	return (
		query.orderby(ip.valid_from.isnull(), order=frappe.qb.asc)
		.orderby(ip.valid_from, order=frappe.qb.desc)
		.orderby(ip.creation, order=frappe.qb.desc)
	).run(as_dict=True)

def insert_item_price(ctx: ItemDetailsCtx):
	"""Insert Item Price if Price List and Price List Rate are specified and currency is the same"""
	if not ctx.price_list or not ctx.rate or ctx.is_internal_supplier or ctx.is_internal_customer:
		return

	stock_settings = frappe.get_cached_doc("Stock Settings")

	if (
		not frappe.db.get_value("Price List", ctx.price_list, "currency", cache=True) == ctx.currency
		or not stock_settings.auto_insert_price_list_rate_if_missing
		or not frappe.has_permission("Item Price", "write")
	):
		return

	transaction_date = (
		getdate(ctx.get("posting_date") or ctx.get("transaction_date") or ctx.get("posting_datetime"))
		or getdate()
	)

	item_prices = get_item_prices_to_auto_update(ctx)
	item_price = next(
		(
			row
			for row in item_prices
			if (not row.valid_from or getdate(row.valid_from) <= transaction_date)
			and (not row.valid_upto or getdate(row.valid_upto) >= transaction_date)
		),
		item_prices[0] if item_prices else None,
	)

	update_based_on_price_list_rate = stock_settings.update_price_list_based_on == "Price List Rate"

	if item_price and item_price.name:
		if not stock_settings.update_existing_price_list_rate:
			return

		rate_to_consider = flt(ctx.price_list_rate) if update_based_on_price_list_rate else flt(ctx.rate)
		price_list_rate = _get_stock_uom_rate(rate_to_consider, ctx)

		if not price_list_rate or item_price.price_list_rate == price_list_rate:
			return

		is_price_valid_for_transaction = (
			not item_price.valid_from or getdate(item_price.valid_from) <= transaction_date
		) and (not item_price.valid_upto or getdate(item_price.valid_upto) >= transaction_date)
		if is_price_valid_for_transaction:
			frappe.db.set_value("Item Price", item_price.name, "price_list_rate", price_list_rate)
			frappe.msgprint(
				_("Item Price updated for {0} in Price List {1}").format(ctx.item_code, ctx.price_list),
				alert=True,
			)
		else:
			# if price is not valid for the transaction date, insert a new price list rate with updated price and future validity

			item_price = frappe.new_doc(
				"Item Price",
				item_code=ctx.item_code,
				price_list_rate=price_list_rate,
				currency=ctx.currency,
				uom=ctx.stock_uom,
				price_list=ctx.price_list,
				valid_from=transaction_date,
			)
			item_price.insert()
			frappe.msgprint(
				_("Item Price added for {0} in Price List - {1}").format(
					get_link_to_form("Item", ctx.item_code), ctx.price_list
				),
				alert=True,
			)
	else:
		rate_to_consider = (
			(flt(ctx.price_list_rate) or flt(ctx.rate)) if update_based_on_price_list_rate else flt(ctx.rate)
		)
		price_list_rate = _get_stock_uom_rate(rate_to_consider, ctx)

		item_price = frappe.get_doc(
			{
				"doctype": "Item Price",
				"price_list": ctx.price_list,
				"item_code": ctx.item_code,
				"currency": ctx.currency,
				"price_list_rate": price_list_rate,
				"uom": ctx.stock_uom,
				"valid_from": transaction_date,
			}
		)
		item_price.insert()
		frappe.msgprint(
			_("Item Price added for {0} in Price List - {1}").format(
				get_link_to_form("Item", ctx.item_code), ctx.price_list
			),
			alert=True,
		)

def _get_item_price_query(
	pctx: ItemPriceCtx,
	item_codes: list[str],
	ignore_party=False,
	force_batch_no=False,
	match_uom=True,
):
	ip = frappe.qb.DocType("Item Price")
	query = frappe.qb.from_(ip).where((ip.item_code.isin(item_codes)) & (ip.price_list == pctx.price_list))
	if match_uom:
		query = query.where(IfNull(ip.uom, "").isin(["", pctx.uom]))

	if force_batch_no:
		query = query.where(ip.batch_no == pctx.batch_no)
	else:
		query = query.where(IfNull(ip.batch_no, "").isin(["", pctx.batch_no]))

	if not ignore_party:
		if pctx.customer:
			query = query.where(
				(ip.customer == pctx.customer)
				| ((IfNull(ip.customer, "") == "") & (IfNull(ip.supplier, "") == ""))
			)
		elif pctx.supplier:
			query = query.where(
				(ip.supplier == pctx.supplier)
				| ((IfNull(ip.customer, "") == "") & (IfNull(ip.supplier, "") == ""))
			)
		else:
			query = query.where((IfNull(ip.customer, "") == "") & (IfNull(ip.supplier, "") == ""))

	if pctx.transaction_date:
		query = query.where(
			(IfNull(ip.valid_from, "2000-01-01") <= pctx.transaction_date)
			& (IfNull(ip.valid_upto, "2500-12-31") >= pctx.transaction_date)
		)

	return query, ip

def _order_item_prices(query, ip, pctx):
	if pctx.customer:
		query = query.orderby(IfNull(ip.customer, ""), order=Order.desc)
	elif pctx.supplier:
		query = query.orderby(IfNull(ip.supplier, ""), order=Order.desc)

	return (
		query.orderby(IfNull(ip.batch_no, ""), order=Order.desc)
		.orderby(ip.valid_from, order=Order.desc)
		.orderby(ip.uom, order=Order.desc)
	)

def get_batch_based_item_price(pctx: ItemPriceCtx | dict | str, item_code) -> float:
	pctx = frappe._dict(parse_json(pctx))
	validate_pricing_context(pctx)
	return _get_batch_based_item_price(pctx, item_code)

def _get_batch_based_item_price(pctx: ItemPriceCtx | dict | str, item_code) -> float:
	pctx = parse_json(pctx)

	item_price = get_item_price(pctx, item_code, force_batch_no=True)
	if not item_price:
		item_price = get_item_price(pctx, item_code, ignore_party=True, force_batch_no=True)

	is_free_item = pctx.get("items", [{}])[0].get("is_free_item")

	if item_price and item_price[0].uom == pctx.uom and not is_free_item:
		return item_price[0].price_list_rate

	return 0.0

def get_price_list_rate_for(ctx: ItemDetailsCtx, item_code):
	"""
	:param customer: link to Customer DocType
	:param supplier: link to Supplier DocType
	:param price_list: str (Standard Buying or Standard Selling)
	:param item_code: str, Item Doctype field item_code
	:param qty: Desired Qty
	:param transaction_date: Date of the price
	"""
	pctx = ItemPriceCtx(
		{
			"item_code": item_code,
			"price_list": ctx.get("price_list"),
			"customer": ctx.get("customer"),
			"supplier": ctx.get("supplier"),
			"uom": ctx.get("uom"),
			"transaction_date": ctx.get("transaction_date"),
			"batch_no": ctx.get("batch_no"),
		}
	)

	item_price_data = 0
	price_list_rate = get_item_price(pctx, item_code, limit=None)
	if price_list_rate:
		if desired_qty := ctx.get("qty"):
			item_price_data = get_prices_fitting_packing_unit(price_list_rate, desired_qty)
	else:
		general_price_list_rate = get_item_price(pctx, item_code, ignore_party=ctx.get("ignore_party"))

		if not general_price_list_rate and ctx.get("uom") != ctx.get("stock_uom"):
			pctx.uom = ctx.get("stock_uom")
			general_price_list_rate = get_item_price(pctx, item_code, ignore_party=ctx.get("ignore_party"))

		if general_price_list_rate:
			item_price_data = general_price_list_rate

	if item_price_data:
		if item_price_data[0].uom == ctx.get("uom"):
			return item_price_data[0].price_list_rate
		elif not ctx.get("price_list_uom_dependant"):
			return flt(item_price_data[0].price_list_rate * flt(ctx.get("conversion_factor", 1)))
		else:
			return item_price_data[0].price_list_rate

def get_prices_fitting_packing_unit(item_prices, desired_qty):
	for item_price in item_prices:
		if not item_price.packing_unit or flt(desired_qty) % flt(item_price.packing_unit) == 0:
			return [item_price]

	return []

def validate_conversion_rate(ctx: ItemDetailsCtx, meta):
	from erpnext.controllers.accounts_controller import validate_conversion_rate

	company_currency = frappe.get_cached_value("Company", ctx.company, "default_currency")
	if not ctx.conversion_rate and ctx.currency == company_currency:
		ctx.conversion_rate = 1.0

	if not ctx.ignore_conversion_rate and ctx.conversion_rate == 1 and ctx.currency != company_currency:
		ctx.conversion_rate = (
			get_exchange_rate(ctx.currency, company_currency, ctx.transaction_date, "for_buying") or 1.0
		)

	# validate currency conversion rate
	validate_conversion_rate(
		ctx.currency, ctx.conversion_rate, meta.get_label("conversion_rate"), ctx.company
	)

	ctx.conversion_rate = flt(
		ctx.conversion_rate,
		get_field_precision(meta.get_field("conversion_rate"), frappe._dict({"fields": ctx})),
	)

	if ctx.price_list:
		if not ctx.plc_conversion_rate and ctx.price_list_currency == frappe.db.get_value(
			"Price List", ctx.price_list, "currency", cache=True
		):
			ctx.plc_conversion_rate = 1.0

		# validate price list currency conversion rate
		if not ctx.price_list_currency:
			throw(_("Price List Currency not selected"))
		else:
			validate_conversion_rate(
				ctx.price_list_currency,
				ctx.plc_conversion_rate,
				meta.get_label("plc_conversion_rate"),
				ctx.company,
			)

			if meta.get_field("plc_conversion_rate"):
				ctx.plc_conversion_rate = flt(
					ctx.plc_conversion_rate,
					get_field_precision(meta.get_field("plc_conversion_rate"), frappe._dict({"fields": ctx})),
				)

def get_party_item_code(ctx: ItemDetailsCtx, item_doc, out: ItemDetails):
	if ctx.transaction_type == "selling" and ctx.customer:
		out.customer_item_code = None

		if ctx.quotation_to and ctx.quotation_to != "Customer":
			return

		customer_item_code = item_doc.get("customer_items", {"customer_name": ctx.customer})

		if customer_item_code:
			out.customer_item_code = customer_item_code[0].ref_code
		else:
			customer_group = frappe.get_cached_value("Customer", ctx.customer, "customer_group")
			customer_group_item_code = item_doc.get("customer_items", {"customer_group": customer_group})
			if customer_group_item_code and not customer_group_item_code[0].customer_name:
				out.customer_item_code = customer_group_item_code[0].ref_code

	if ctx.transaction_type == "buying" and ctx.supplier:
		item_supplier = item_doc.get("supplier_items", {"supplier": ctx.supplier})
		out.supplier_part_no = item_supplier[0].supplier_part_no if item_supplier else None

def get_tax_withholding_category(ctx: ItemDetailsCtx, item_doc, out: ItemDetails):
	"""
	Get tax withholding category for the item based on the transaction type and party.
	"""

	tax_withholding_category = None
	field = (
		"sales_tax_withholding_category"
		if ctx.transaction_type == "selling"
		else "purchase_tax_withholding_category"
	)

	if item_doc.get(field):
		tax_withholding_category = item_doc.get(field)
	elif ctx.transaction_type == "buying" and ctx.supplier:
		tax_withholding_category = frappe.get_cached_value(
			"Supplier", ctx.supplier, "tax_withholding_category"
		)
	elif ctx.transaction_type == "selling" and ctx.customer:
		tax_withholding_category = frappe.get_cached_value(
			"Customer", ctx.customer, "tax_withholding_category"
		)

	out.tax_withholding_category = tax_withholding_category

def get_pos_profile_item_details_(ctx: ItemDetailsCtx, company, pos_profile=None, update_data=False):
	res = frappe._dict()

	if not frappe.flags.pos_profile and not pos_profile:
		pos_profile = frappe.flags.pos_profile = get_pos_profile(company, ctx.pos_profile)

	if pos_profile:
		for fieldname in ("income_account", "cost_center", "warehouse", "expense_account"):
			if (not ctx.get(fieldname) or update_data) and pos_profile.get(fieldname):
				res[fieldname] = pos_profile.get(fieldname)

		if res.get("warehouse"):
			res.actual_qty = get_bin_details(ctx.item_code, res.warehouse, include_child_warehouses=True).get(
				"actual_qty"
			)

	return res

def get_conversion_factor(item_code, uom):
	item = frappe.get_cached_value("Item", item_code, ["variant_of", "stock_uom"], as_dict=True)
	if not item_code or not item or uom == item.stock_uom:
		return {"conversion_factor": 1.0}

	item_codes = [item_code]
	if item.variant_of:
		item_codes.append(item.variant_of)

	parent = frappe.qb.DocType("Item")
	child = frappe.qb.DocType("UOM Conversion Detail")
	query = (
		frappe.qb.from_(parent)
		.join(child)
		.on(parent.name == child.parent)
		.select(child.conversion_factor)
		.where((parent.name.isin(item_codes)) & (child.uom == uom))
		.orderby(parent.has_variants)
		.limit(1)
	)
	conversion_factor = query.run(pluck="conversion_factor")

	if not conversion_factor:
		conversion_factor = get_uom_conv_factor(uom, item.stock_uom)
	else:
		conversion_factor = conversion_factor[0]

	return {"conversion_factor": conversion_factor or 1.0}

def get_projected_qty(item_code, warehouse):
	# record-level read on the item, as get_item_details() in this file already does. Nothing in the
	# tree calls this, so no caller's roles constrain the choice.
	frappe.has_permission("Item", doc=item_code, throw=True)

	return {
		"projected_qty": frappe.db.get_value(
			"Bin", {"item_code": item_code, "warehouse": warehouse}, "projected_qty"
		)
	}

def get_company_total_stock(item_code, company):
	bin = frappe.qb.DocType("Bin")
	wh = frappe.qb.DocType("Warehouse")

	return (
		frappe.qb.from_(bin)
		.inner_join(wh)
		.on(bin.warehouse == wh.name)
		.select(Sum(bin.actual_qty))
		.where((wh.company == company) & (bin.item_code == item_code))
	).run()[0][0]

def get_batch_qty(batch_no, warehouse, item_code):
	from erpnext.stock.doctype.batch import batch

	if batch_no:
		return {"actual_batch_qty": batch.get_batch_qty(batch_no, warehouse)}

def apply_price_list(ctx, as_doc=False, doc=None):
	validate_pricing_context(ctx)
	return _apply_price_list(ctx, as_doc, doc)

def apply_price_list_on_item(ctx, doc=None):
	item_doc = frappe.get_cached_doc("Item", ctx.item_code)

	source_row = get_rate_locked_source_row(ctx, doc)
	if source_row:
		item_details = frappe._dict()
		lock_source_rate(item_details, source_row)
	else:
		item_details = get_price_list_rate(ctx, item_doc)

	ctx.conversion_factor = flt(ctx.conversion_factor) or get_conversion_factor(ctx.item_code, ctx.uom).get(
		"conversion_factor", 1
	)
	ctx.stock_qty = flt(ctx.qty) * flt(ctx.conversion_factor)

	if not source_row:
		item_details.update(get_pricing_rule_for_item(ctx, doc=doc))

	return item_details

def get_price_list_currency_and_exchange_rate(ctx: ItemDetailsCtx):
	if not ctx.price_list:
		return {}

	if ctx.doctype in ["Quotation", "Sales Order", "Delivery Note", "Sales Invoice", "POS Invoice"]:
		ctx.update({"exchange_rate": "for_selling"})
	elif ctx.doctype in ["Supplier Quotation", "Purchase Order", "Purchase Receipt", "Purchase Invoice"]:
		ctx.update({"exchange_rate": "for_buying"})

	price_list_details = get_price_list_details(ctx.price_list)

	price_list_currency = price_list_details.get("currency")
	price_list_uom_dependant = price_list_details.get("price_list_uom_dependant")

	plc_conversion_rate = ctx.plc_conversion_rate
	company_currency = get_company_currency(ctx.company)

	if (not plc_conversion_rate) or (
		price_list_currency and ctx.price_list_currency and price_list_currency != ctx.price_list_currency
	):
		# cksgb 19/09/2016: added args.transaction_date as posting_date argument for get_exchange_rate
		plc_conversion_rate = (
			get_exchange_rate(price_list_currency, company_currency, ctx.transaction_date, ctx.exchange_rate)
			or plc_conversion_rate
		)

	return frappe._dict(
		{
			"price_list_currency": price_list_currency,
			"price_list_uom_dependant": price_list_uom_dependant,
			"plc_conversion_rate": plc_conversion_rate or 1,
		}
	)

def get_default_bom(item_code=None):
	def _get_bom(item):
		bom = frappe.get_all("BOM", dict(item=item, is_active=True, is_default=True, docstatus=1), limit=1)
		return bom[0].name if bom else None

	if not item_code:
		return

	bom_name = _get_bom(item_code)

	template_item = frappe.db.get_value("Item", item_code, "variant_of")
	if not bom_name and template_item:
		bom_name = _get_bom(template_item)

	return bom_name

def get_valuation_rate(item_code, company, warehouse=None):
	"""Whitelisted entry point: authorise the item, then return its cost price."""
	frappe.has_permission("Item", doc=item_code, throw=True)
	frappe.has_permission("Company", doc=company, ptype="select", throw=True)

	return _get_valuation_rate(item_code, company, warehouse)

def _get_valuation_rate(item_code, company, warehouse=None):
	# no guard here: set_valuation_rate calls this for the item and every Product Bundle component,
	# and a caller entitled to the bundle is not necessarily entitled to each component.
	if frappe.get_cached_value("Warehouse", warehouse, "is_group"):
		return {"valuation_rate": 0.0}

	item = get_item_defaults(item_code, company)
	item_group = get_item_group_defaults(item_code, company)
	brand = get_brand_defaults(item_code, company)
	if item.get("is_stock_item"):
		if not warehouse:
			warehouse = (
				item.get("default_warehouse")
				or item_group.get("default_warehouse")
				or brand.get("default_warehouse")
			)

		return frappe.db.get_value(
			"Bin", {"item_code": item_code, "warehouse": warehouse}, ["valuation_rate"], as_dict=True
		) or {"valuation_rate": item.get("valuation_rate") or 0}

	elif not item.get("is_stock_item"):
		pi_item = frappe.qb.DocType("Purchase Invoice Item")
		valuation_rate = (
			frappe.qb.from_(pi_item)
			.select(Sum(pi_item.base_net_amount) / Sum(pi_item.qty * pi_item.conversion_factor))
			.where((pi_item.docstatus == 1) & (pi_item.item_code == item_code))
		).run()

		if valuation_rate:
			return {"valuation_rate": valuation_rate[0][0] or 0.0}
	else:
		return {"valuation_rate": 0.0}

def get_gross_profit(out: ItemDetails):
	if out.valuation_rate:
		out.update({"gross_profit": ((out.base_rate - out.valuation_rate) * out.stock_qty)})

	return out

def get_serial_no(_args, serial_nos=None, sales_order=None):
	serial_nos = serial_nos or []
	return serial_nos

def update_party_blanket_order(ctx: ItemDetailsCtx, out: ItemDetails | dict):
	if out["against_blanket_order"]:
		blanket_order_details = _get_blanket_order_details(ctx)
		if blanket_order_details:
			out.update(blanket_order_details)

def get_blanket_order_details(ctx: ItemDetailsCtx):
	validate_pricing_context(ctx)
	return _get_blanket_order_details(ctx)

def validate_dates(self):
	if self.planned_start_date and self.planned_end_date:
		if get_datetime(self.planned_end_date) < get_datetime(self.planned_start_date):
			frappe.throw(_("Planned End Date cannot be before Planned Start Date"))

	if self.actual_start_date and self.actual_end_date:
		if self.actual_end_date < self.actual_start_date:
			frappe.throw(_("Actual End Date cannot be before Actual Start Date"))

def validate_fg_warehouse_for_reservation(self):
	if (
		self.reserve_stock
		and self.sales_order
		and not self.subcontracting_inward_order
		and not self.production_plan_sub_assembly_item
	):
		warehouses = frappe.get_all(
			"Sales Order Item",
			filters={"parent": self.sales_order, "item_code": self.production_item},
			pluck="warehouse",
		)

		if self.fg_warehouse not in warehouses:
			frappe.throw(
				_("Warehouse {0} is not allowed for Sales Order {1}, it should be {2}").format(
					self.fg_warehouse, self.sales_order, warehouses[0]
				),
				title=_("Target Warehouse Reservation Error"),
			)

def enable_reserve_stock_for_produced_serial_no(self):
	"""Reserve the produced serial nos for a Sales Order Item with ensure delivery by serial no."""

	if self.reserve_stock or not self.sales_order_item:
		return

	if not frappe.db.get_single_value("Stock Settings", "enable_stock_reservation"):
		return

	if frappe.db.get_value(
		"Sales Order Item", self.sales_order_item, "ensure_delivery_based_on_produced_serial_no"
	):
		self.reserve_stock = 1

def set_reserve_stock(self):
	for row in self.required_items:
		row.reserve_stock = self.reserve_stock

def enable_auto_reserve_stock(self):
	if self.is_new() and frappe.db.get_single_value("Stock Settings", "auto_reserve_stock"):
		self.reserve_stock = 1

def set_skip_transfer_for_operations(self):
	if not self.track_semi_finished_goods:
		return

	for op in self.operations:
		op.skip_material_transfer = self.skip_transfer

def validate_operations_sequence(self):
	if all([not op.sequence_id for op in self.operations]):
		for op in self.operations:
			op.sequence_id = op.idx
	else:
		sequence_id = 1
		for op in self.operations:
			if op.idx == 1 and op.sequence_id != 1:
				frappe.throw(
					_("Row #1: Sequence ID must be 1 for Operation {0}.").format(
						frappe.bold(op.operation)
					)
				)
			elif op.sequence_id != sequence_id and op.sequence_id != sequence_id + 1:
				frappe.throw(
					_("Row #{0}: Sequence ID must be {1} or {2} for Operation {3}.").format(
						op.idx,
						frappe.bold(sequence_id),
						frappe.bold(sequence_id + 1),
						frappe.bold(op.operation),
					)
				)
			sequence_id = op.sequence_id

def validate_subcontracting_inward_order(self):
	if scio := self.subcontracting_inward_order:
		if self.source_warehouse != (
			rm_receipt_warehouse := frappe.get_cached_value(
				"Subcontracting Inward Order",
				scio,
				"customer_warehouse",
			)
		):
			frappe.throw(
				_(
					"Source Warehouse {0} must be same as Customer Warehouse {1} in the Subcontracting Inward Order."
				).format(
					get_link_to_form("Warehouse", self.source_warehouse),
					get_link_to_form("Warehouse", rm_receipt_warehouse),
				)
			)

		if self.fg_warehouse != (
			delivery_warehouse := frappe.get_cached_value(
				"Subcontracting Inward Order Item",
				self.subcontracting_inward_order_item,
				"delivery_warehouse",
			)
		):
			frappe.throw(
				_(
					"Target Warehouse {0} must be same as Delivery Warehouse {1} in the Subcontracting Inward Order Item."
				).format(
					get_link_to_form("Warehouse", self.fg_warehouse),
					get_link_to_form(
						"Warehouse",
						delivery_warehouse,
					),
				)
			)

		possible_customer_provided_items = frappe.get_all(
			"Subcontracting Inward Order Received Item",
			{
				"reference_name": self.subcontracting_inward_order_item,
				"is_customer_provided_item": 1,
				"docstatus": 1,
			},
			["rm_item_code", "received_qty", "returned_qty", "work_order_qty"],
		)
		item_codes = []
		for item in self.required_items:
			if item.is_customer_provided_item:
				if item.source_warehouse != self.source_warehouse:
					frappe.throw(
						_(
							"Row #{0}: Source Warehouse {1} for item {2} must be same as Source Warehouse {3} in the Work Order."
						).format(
							item.idx,
							get_link_to_form("Warehouse", item.source_warehouse),
							get_link_to_form("Item", item.item_code),
							get_link_to_form("Warehouse", self.source_warehouse),
						)
					)
				elif item.item_code in item_codes:
					frappe.throw(
						_("Row #{0}: Customer Provided Item {1} cannot be added multiple times.").format(
							item.idx,
							get_link_to_form("Item", item.item_code),
						)
					)
				else:
					row = next(
						(i for i in possible_customer_provided_items if i.rm_item_code == item.item_code),
						None,
					)
					if row:
						if item.required_qty > row.received_qty - row.returned_qty - row.work_order_qty:
							frappe.throw(
								_(
									"Row #{0}: Customer Provided Item {1} has insufficient quantity in the Subcontracting Inward Order. Available quantity is {2}."
								).format(
									item.idx,
									get_link_to_form("Item", item.item_code),
									frappe.bold(row.received_qty - row.returned_qty - row.work_order_qty),
								)
							)
						else:
							item_codes.append(item.item_code)
					else:
						frappe.throw(
							_(
								"Row #{0}: Customer Provided Item {1} does not exist in the Required Items table linked to the Subcontracting Inward Order."
							).format(
								item.idx,
								get_link_to_form("Item", item.item_code),
							)
						)
			elif frappe.get_cached_value("Warehouse", item.source_warehouse, "customer"):
				frappe.throw(
					_(
						"Row #{0}: Source Warehouse {1} for item {2} cannot be a customer warehouse."
					).format(
						item.idx,
						get_link_to_form("Warehouse", item.source_warehouse),
						get_link_to_form("Item", item.item_code),
					)
				)

def set_warehouses(self):
	for row in self.required_items:
		if not row.source_warehouse:
			row.source_warehouse = self.source_warehouse

def reset_use_multi_level_bom(self):
	previous = None if self.is_new() else self.get_doc_before_save()
	self.sync_operations_with_bom(previous)

def sync_operations_with_bom(self, previous):
	if previous is None:
		return

	if previous.bom_no != self.bom_no or previous.use_multi_level_bom != self.use_multi_level_bom:
		self.get_items_and_operations_from_bom()
	elif flt(previous.qty) != flt(self.qty) and flt(previous.qty):
		self.scale_saved_operation_time(previous)

def scale_saved_operation_time(self, previous):
	saved_rows = {row.name: row for row in previous.get("operations")}
	fixed_flags = self.get_fixed_time_flags()
	occurrence = {}
	for d in self.get("operations"):
		key = (d.bom or self.bom_no, d.operation)
		idx = occurrence[key] = occurrence.get(key, -1) + 1
		flags = fixed_flags.get(key, [])
		is_fixed = flags[idx % len(flags)] if flags else False
		saved = saved_rows.get(d.name)
		if not saved or is_fixed or flt(saved.time_in_mins) != flt(d.time_in_mins):
			continue
		d.time_in_mins = flt(saved.time_in_mins) * flt(self.qty) / flt(previous.qty)
	self.calculate_operating_cost()

def get_fixed_time_flags(self):
	boms = {d.bom or self.bom_no for d in self.get("operations")}
	flags = {}
	for row in frappe.get_all(
		"BOM Operation",
		filters={"parent": ["in", list(boms)], "parenttype": "BOM"},
		fields=["parent", "operation", "fixed_time"],
		order_by="idx",
	):
		flags.setdefault((row.parent, row.operation), []).append(cint(row.fixed_time))
	return flags

def validate_workstation_type(self):
	if not self.docstatus.is_submitted():
		return

	for row in self.operations:
		if not row.workstation and not row.workstation_type:
			frappe.throw(
				_("Row {0}: Workstation or Workstation Type is mandatory for an operation {1}").format(
					row.idx, row.operation
				)
			)

def validate_sales_order(self):
	if self.production_plan_sub_assembly_item:
		return

	production_item = self.production_item

	if self.material_request_item and (
		mr_plan_item := frappe.get_value(
			"Material Request Item", self.material_request_item, "material_request_plan_item"
		)
	):
		if main_item_code := frappe.get_value(
			"Material Request Plan Item", mr_plan_item, "main_item_code"
		):
			production_item = main_item_code

	if self.sales_order:
		check_on_hold_or_closed_status("Sales Order", self.sales_order)

		SalesOrder = frappe.qb.DocType("Sales Order")
		SalesOrderItem = frappe.qb.DocType("Sales Order Item")
		PackedItem = frappe.qb.DocType("Packed Item")
		ProductBundleItem = frappe.qb.DocType("Product Bundle Item")

		so_query = (
			frappe.qb.from_(SalesOrder)
			.inner_join(SalesOrderItem)
			.on(SalesOrderItem.parent == SalesOrder.name)
			.left_join(ProductBundleItem)
			.on(ProductBundleItem.parent == SalesOrderItem.item_code)
			.select(SalesOrder.name, SalesOrder.project, SalesOrderItem.delivery_date)
			.where(
				(SalesOrder.skip_delivery_note == 0)
				& (SalesOrder.docstatus == 1)
				& (SalesOrder.name == self.sales_order)
				& (
					(SalesOrderItem.item_code == production_item)
					| (ProductBundleItem.item_code == production_item)
				)
			)
		)

		if self.sales_order_item:
			so_query = so_query.where(SalesOrderItem.name == self.sales_order_item)

		so = so_query.run(as_dict=1)

		if not so:
			packed_so_query = (
				frappe.qb.from_(SalesOrder)
				.inner_join(SalesOrderItem)
				.on(SalesOrderItem.parent == SalesOrder.name)
				.inner_join(PackedItem)
				.on(
					(PackedItem.parent == SalesOrder.name)
					& (PackedItem.parent_detail_docname == SalesOrderItem.name)
				)
				.select(SalesOrder.name, SalesOrder.project, SalesOrderItem.delivery_date)
				.where(
					(SalesOrder.name == self.sales_order)
					& (SalesOrder.skip_delivery_note == 0)
					& (SalesOrderItem.item_code == PackedItem.parent_item)
					& (SalesOrder.docstatus == 1)
					& (PackedItem.item_code == production_item)
				)
			)

			if self.sales_order_item:
				packed_so_query = packed_so_query.where(
					(PackedItem.name == self.sales_order_item)
					| (SalesOrderItem.name == self.sales_order_item)
				)

			so = packed_so_query.run(as_dict=1)

		if len(so):
			if not self.expected_delivery_date:
				self.expected_delivery_date = so[0].delivery_date

			if so[0].project:
				self.project = so[0].project

			if not self.material_request:
				self.validate_work_order_against_so()
		else:
			frappe.throw(_("Sales Order {0} is not valid").format(self.sales_order))

def set_default_warehouse(self):
	if not self.wip_warehouse and not self.skip_transfer:
		self.wip_warehouse = frappe.get_cached_value("Company", self.company, "default_wip_warehouse")
	if not self.fg_warehouse:
		self.fg_warehouse = self.get_default_fg_warehouse()

